body.value:
(* Linear scaling of the 4-20mA raw signal to engineering units. *)
PV := Raw_Signal * Scaling_Slope + Scaling_Offset;
(* Wire-break style fault: a healthy 4-20mA loop never drops below ~2mA. *)
General_Fault := Alarm_Enable AND (Raw_Signal < 2.0);
High_Alarm := Alarm_Enable AND (PV > PV_High);
Low_Alarm := Alarm_Enable AND (PV < PV_Low);

Bool_Out := Bool_In;
Alarm_Active := (Alarm_OnTrue AND Bool_In) OR (Alarm_OnFalse AND NOT Bool_In);
IF Reset_Latch THEN
    Latched_Status := FALSE;
ELSIF Latch_Enable AND Alarm_Active THEN
    Latched_Status := TRUE;
END_IF;

(* Pass-through of the field contact (debounce not modeled). *)
DI_Out := DI_Raw;
Fault_State := FALSE;

ActiveIsA := NOT AlternateEnable;
IF Enable AND StartRequest AND NOT Inhibit THEN
    CmdPumpA := ActiveIsA AND NOT PumpA_Fault;
    CmdPumpB := (NOT ActiveIsA OR PumpA_Fault) AND NOT PumpB_Fault;
ELSE
    CmdPumpA := FALSE;
    CmdPumpB := FALSE;
END_IF;
IF ForcePumpA THEN
    CmdPumpA := Enable AND NOT Inhibit;
    CmdPumpB := FALSE;
END_IF;
IF ForcePumpB THEN
    CmdPumpA := FALSE;
    CmdPumpB := Enable AND NOT Inhibit;
END_IF;
SwitchedDueToDuty := DutyElapsed;
SwitchedDueToFailure := PumpA_Fault OR PumpB_Fault;
Alarm_FailedStart_A := PumpA_Fault;
Alarm_FailedStart_B := PumpB_Fault;
Alarm_NoAvailablePump := PumpA_Fault AND PumpB_Fault;

IF Inhibit OR Stop_Cmd THEN
    Motor_Start_Out := FALSE;
ELSIF Start_Cmd THEN
    Motor_Start_Out := TRUE;
END_IF;
FB_Running := Motor_Start_Out;
FB_HighSpeed := Motor_Start_Out AND Speed_High_Cmd;
FB_LowSpeed := Motor_Start_Out AND Speed_Low_Cmd AND NOT Speed_High_Cmd;
FB_Trip := FALSE;
Alarm_Speed_Error := Speed_High_Cmd AND Speed_Low_Cmd;

IF Inhibit OR Stop_Cmd THEN
    Motor_Start_Out := FALSE;
ELSIF Start_Cmd THEN
    Motor_Start_Out := TRUE;
END_IF;
FB_Running := Motor_Start_Out;
FB_Trip := FALSE;
Alarm_Start_Fail := FALSE;
Alarm_Stop_Fail := FALSE;

IF Inhibit OR Stop_Cmd THEN
    FB_Running := FALSE;
ELSIF Start_Cmd THEN
    FB_Running := TRUE;
END_IF;
IF FB_Running THEN
    Speed_Out := Speed_SP;
ELSE
    Speed_Out := 0.0;
END_IF;
FB_Ready := NOT Inhibit;
FB_Fault := FALSE;
FB_ActualSpeed := Speed_Out;
Alarm_Speed_Deviation := FALSE;
Alarm_Comm_Fail := FALSE;

PV_High_Alarm := PV > PV_High;
PV_Low_Alarm := PV < PV_Low;
Deviation_Alarm := ABS(SP - PV) > Deviation_Limit;
(* Bounded proportional control law (single-block, stateless). *)
IF Inhibit THEN
    XOUT := MV_MIN;
ELSIF AUTO THEN
    XOUT := LIMIT(MV_MIN, X0 + KP * (SP - PV), MV_MAX);
ELSE
    XOUT := X0;
END_IF;

IF PrimaryPV > 0.0 THEN
    ActiveRatio := SecondaryPV / PrimaryPV;
ELSE
    ActiveRatio := 0.0;
END_IF;
RatioErr := ActiveRatio - RatioSP;
IF Inhibit THEN
    SlaveSP := MV_MIN;
ELSIF Auto THEN
    SlaveSP := LIMIT(MV_MIN, PrimaryPV * RatioSP + Bias, MV_MAX);
ELSE
    SlaveSP := ManOut;
END_IF;

IF IN <= Split_Point THEN
    OUT1 := Output1_End;
    OUT2 := Output2_Start;
ELSE
    OUT1 := Output1_Start;
    OUT2 := Output2_End;
END_IF;

IF Inhibit THEN
    Valve_Position := Close_Limit;
ELSIF Manual_Mode THEN
    Valve_Position := LIMIT(Close_Limit, Manual_Position, Open_Limit);
ELSE
    Valve_Position := LIMIT(Close_Limit, Control_Signal, Open_Limit);
END_IF;
Feedback_Pos := Valve_Position;
Valve_Moving := FALSE;
Position_Error := FALSE;
Alarm := Inhibit;

IF Inhibit THEN
    Valve_Open_Out := FALSE;
    Valve_Close_Out := TRUE;
ELSE
    Valve_Open_Out := Open_Cmd AND NOT Close_Cmd;
    Valve_Close_Out := Close_Cmd OR NOT Open_Cmd;
END_IF;
FB_Opened := Valve_Open_Out;
FB_Closed := NOT Valve_Open_Out;
Alarm_Position_Error := FALSE;
Alarm_General := Inhibit;

Voted_Output := (Input1 + Input2 + Input3) / 3.0;
Sensor1_Fault := FALSE;
Sensor2_Fault := FALSE;
Sensor3_Fault := FALSE;
Alarm_Voting_Error := FALSE;
Healthy_Sensors_Count := 3;

AT_101(
    PV_High := 50.0,
    Alarm_Enable := TRUE);
AT_103(
    PV_High := 35.0,
    Alarm_Enable := TRUE);
SP101_PctNorm_DIV := SP101_PctCmd / 100.0;
SP101_PctScaled_MULT := SP101_PctNorm_DIV * 59.0;
SP101_PctOffset_ADD := SP101_PctScaled_MULT + 16.0;
SP101_PctToFrac_DIV := SP101_PctOffset_ADD / 100.0;
SP101_SP_EU_MULT := SP101_PctToFrac_DIV * 5000.0;
DL101_MULT := SP101_SP_EU_MULT * 0.1;
FT_101(
    PV_High := 5500.0,
    PV_Low := 450.0,
    Scaling_Slope := 312.5,
    Scaling_Offset := -1250.0,
    Alarm_Enable := TRUE);
FC_101(
    AUTO := TRUE,
    PV := FT_101.PV,
    SP := SP101_SP_EU_MULT,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := 0.0,
    KP := 2.5,
    TR := 0.8,
    TD := 0.2,
    Deviation_Limit := DL101_MULT,
    Inhibit := FT_101.General_Fault);
SP102_PctNorm_DIV := SP102_PctCmd / 100.0;
SP102_PctScaled_MULT := SP102_PctNorm_DIV * 59.0;
SP102_PctOffset_ADD := SP102_PctScaled_MULT + 16.0;
SP102_PctToFrac_DIV := SP102_PctOffset_ADD / 100.0;
SP102_SP_EU_MULT := SP102_PctToFrac_DIV * 3000.0;
DL102_MULT := SP102_SP_EU_MULT * 0.1;
FT_102(
    PV_High := 3300.0,
    PV_Low := 270.0,
    Scaling_Slope := 187.5,
    Scaling_Offset := -750.0,
    Alarm_Enable := TRUE);
FC_102(
    AUTO := TRUE,
    PV := FT_102.PV,
    SP := SP102_SP_EU_MULT,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := 0.0,
    KP := 2.5,
    TR := 0.8,
    TD := 0.2,
    Deviation_Limit := DL102_MULT,
    Inhibit := FT_102.General_Fault);
Contamination_OR := AT_101.High_Alarm OR AT_103.High_Alarm;
LT_104(
    PV_Low := 2.0,
    Alarm_Enable := TRUE);
LT_105(
    Alarm_Enable := TRUE);
XV_102(
    Inhibit := Contamination_OR);
XV102NotOpen_NOT := NOT XV_102.FB_Opened;
FV101_Inhibit_OR := XV102NotOpen_NOT OR Contamination_OR OR LT_104.Low_Alarm OR LT_105.High_Alarm OR FT_101.General_Fault;
FV_101(
    Control_Signal := FC_101.XOUT,
    Manual_Mode := FALSE,
    Manual_Position := 0.0,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Inhibit := FV101_Inhibit_OR);
FV102_Inhibit_OR := XV102NotOpen_NOT OR Contamination_OR OR LT_104.Low_Alarm OR LT_105.High_Alarm OR FT_102.General_Fault;
FV_102(
    Control_Signal := FC_102.XOUT,
    Manual_Mode := FALSE,
    Manual_Position := 0.0,
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Inhibit := FV102_Inhibit_OR);
SP101_1p1_MULT := SP101_SP_EU_MULT * 1.1;
SP101_PV_GT_HighThresh := (FT_101.PV > SP101_1p1_MULT);
SP101_0p9_MULT := SP101_SP_EU_MULT * 0.9;
SP101_PV_LT_LowThresh := (FT_101.PV < SP101_0p9_MULT);
SP101_DevBand_OR := SP101_PV_GT_HighThresh OR SP101_PV_LT_LowThresh;
SP101_DevDelay_TON(
    IN := SP101_DevBand_OR,
    PT := T#30s);
SP102_1p1_MULT := SP102_SP_EU_MULT * 1.1;
SP102_PV_GT_HighThresh := (FT_102.PV > SP102_1p1_MULT);
SP102_0p9_MULT := SP102_SP_EU_MULT * 0.9;
SP102_PV_LT_LowThresh := (FT_102.PV < SP102_0p9_MULT);
SP102_DevBand_OR := SP102_PV_GT_HighThresh OR SP102_PV_LT_LowThresh;
SP102_DevDelay_TON(
    IN := SP102_DevBand_OR,
    PT := T#30s);

(* Outputs published to other sections / HMI. *)
FT101_Flow_PV := FT_101.PV;
FT102_Flow_PV := FT_102.PV;
AT101_Analyzer_PV := AT_101.PV;
AT103_Analyzer_PV := AT_103.PV;
LT104_Level_PV := LT_104.PV;
LT105_Level_PV := LT_105.PV;
FC101_MV_Out := FC_101.XOUT;
FC102_MV_Out := FC_102.XOUT;
FV101_Valve_Position := FV_101.Valve_Position;
FV102_Valve_Position := FV_102.Valve_Position;
FlowDevAlarm101 := SP101_DevDelay_TON.Q;
FlowDevAlarm102 := SP102_DevDelay_TON.Q;

FT_101(
    PV_Low := 50.0,
    Scaling_Slope := 31.25,
    Scaling_Offset := -125.0,
    Alarm_Enable := TRUE);
FT_102(
    Scaling_Slope := 31.25,
    Scaling_Offset := -125.0);
PIT_105(
    Alarm_Enable := TRUE);
PIT_106(
    Alarm_Enable := TRUE);
DownstreamOutOfRange := PIT_105.Low_Alarm OR PIT_105.High_Alarm OR PIT_106.Low_Alarm OR PIT_106.High_Alarm;
LowFlowOff := (FT_101.PV > 50.0);
LowFlowOn := (FT_101.PV < 50.0);
LowFlowLatch := (LowFlowOn OR LowFlowLatch) AND NOT LowFlowOff;
AutoEnableInv := NOT LowFlowLatch;
FIC_104(
    AUTO := AutoEnableInv,
    PV := FT_102.PV,
    SP := FFIC_103.SlaveSP);
PT_108(
    PV_High := 9.0,
    PV_Low := 5.0,
    Alarm_Enable := TRUE);
SupplyPressureTrip := PT_108.Low_Alarm OR PT_108.High_Alarm;
ValveInhibit := DownstreamOutOfRange OR SupplyPressureTrip;
FV_105(
    Control_Signal := FIC_104.XOUT,
    Timeout := T#2s,
    Inhibit := ValveInhibit);
PT_103(
    Alarm_Enable := TRUE);
PT_104(
    Alarm_Enable := TRUE);
RES_SCREEN_1();
RES_SCREEN_2();
RES_SCREEN_3();
RES_SCREEN_4();
SW_SCREEN_1();
SW_SCREEN_2();
SW_SCREEN_3();
SW_SCREEN_4();
SW_SCREEN_5();
SW_SCREEN_6();
Res1Others := SW_SCREEN_1.Bool_Out OR SW_SCREEN_2.Bool_Out OR SW_SCREEN_3.Bool_Out OR SW_SCREEN_4.Bool_Out OR SW_SCREEN_5.Bool_Out OR SW_SCREEN_6.Bool_Out OR RES_SCREEN_2.Bool_Out OR RES_SCREEN_3.Bool_Out OR RES_SCREEN_4.Bool_Out;
Res1WithAnother := RES_SCREEN_1.Bool_Out AND Res1Others;
Res2Others := SW_SCREEN_1.Bool_Out OR SW_SCREEN_2.Bool_Out OR SW_SCREEN_3.Bool_Out OR SW_SCREEN_4.Bool_Out OR SW_SCREEN_5.Bool_Out OR SW_SCREEN_6.Bool_Out OR RES_SCREEN_1.Bool_Out OR RES_SCREEN_3.Bool_Out OR RES_SCREEN_4.Bool_Out;
Res2WithAnother := RES_SCREEN_2.Bool_Out AND Res2Others;
Res3Others := SW_SCREEN_1.Bool_Out OR SW_SCREEN_2.Bool_Out OR SW_SCREEN_3.Bool_Out OR SW_SCREEN_4.Bool_Out OR SW_SCREEN_5.Bool_Out OR SW_SCREEN_6.Bool_Out OR RES_SCREEN_1.Bool_Out OR RES_SCREEN_2.Bool_Out OR RES_SCREEN_4.Bool_Out;
Res3WithAnother := RES_SCREEN_3.Bool_Out AND Res3Others;
Res4Others := SW_SCREEN_1.Bool_Out OR SW_SCREEN_2.Bool_Out OR SW_SCREEN_3.Bool_Out OR SW_SCREEN_4.Bool_Out OR SW_SCREEN_5.Bool_Out OR SW_SCREEN_6.Bool_Out OR RES_SCREEN_1.Bool_Out OR RES_SCREEN_2.Bool_Out OR RES_SCREEN_3.Bool_Out;
Res4WithAnother := RES_SCREEN_4.Bool_Out AND Res4Others;
Screen1Others := SW_SCREEN_2.Bool_Out OR SW_SCREEN_3.Bool_Out OR SW_SCREEN_4.Bool_Out OR SW_SCREEN_5.Bool_Out OR SW_SCREEN_6.Bool_Out OR RES_SCREEN_1.Bool_Out OR RES_SCREEN_2.Bool_Out OR RES_SCREEN_3.Bool_Out OR RES_SCREEN_4.Bool_Out;
Screen1WithAnother := SW_SCREEN_1.Bool_Out AND Screen1Others;
Screen2Others := SW_SCREEN_1.Bool_Out OR SW_SCREEN_3.Bool_Out OR SW_SCREEN_4.Bool_Out OR SW_SCREEN_5.Bool_Out OR SW_SCREEN_6.Bool_Out OR RES_SCREEN_1.Bool_Out OR RES_SCREEN_2.Bool_Out OR RES_SCREEN_3.Bool_Out OR RES_SCREEN_4.Bool_Out;
Screen2WithAnother := SW_SCREEN_2.Bool_Out AND Screen2Others;
Screen3Others := SW_SCREEN_1.Bool_Out OR SW_SCREEN_2.Bool_Out OR SW_SCREEN_4.Bool_Out OR SW_SCREEN_5.Bool_Out OR SW_SCREEN_6.Bool_Out OR RES_SCREEN_1.Bool_Out OR RES_SCREEN_2.Bool_Out OR RES_SCREEN_3.Bool_Out OR RES_SCREEN_4.Bool_Out;
Screen3WithAnother := SW_SCREEN_3.Bool_Out AND Screen3Others;
Screen4Others := SW_SCREEN_1.Bool_Out OR SW_SCREEN_2.Bool_Out OR SW_SCREEN_3.Bool_Out OR SW_SCREEN_5.Bool_Out OR SW_SCREEN_6.Bool_Out OR RES_SCREEN_1.Bool_Out OR RES_SCREEN_2.Bool_Out OR RES_SCREEN_3.Bool_Out OR RES_SCREEN_4.Bool_Out;
Screen4WithAnother := SW_SCREEN_4.Bool_Out AND Screen4Others;
Screen5Others := SW_SCREEN_1.Bool_Out OR SW_SCREEN_2.Bool_Out OR SW_SCREEN_3.Bool_Out OR SW_SCREEN_4.Bool_Out OR SW_SCREEN_6.Bool_Out OR RES_SCREEN_1.Bool_Out OR RES_SCREEN_2.Bool_Out OR RES_SCREEN_3.Bool_Out OR RES_SCREEN_4.Bool_Out;
Screen5WithAnother := SW_SCREEN_5.Bool_Out AND Screen5Others;
Screen6Others := SW_SCREEN_1.Bool_Out OR SW_SCREEN_2.Bool_Out OR SW_SCREEN_3.Bool_Out OR SW_SCREEN_4.Bool_Out OR SW_SCREEN_5.Bool_Out OR RES_SCREEN_1.Bool_Out OR RES_SCREEN_2.Bool_Out OR RES_SCREEN_3.Bool_Out OR RES_SCREEN_4.Bool_Out;
Screen6WithAnother := SW_SCREEN_6.Bool_Out AND Screen6Others;
ScreenConflict := Screen1WithAnother OR Screen2WithAnother OR Screen3WithAnother OR Screen4WithAnother OR Screen5WithAnother OR Screen6WithAnother OR Res1WithAnother OR Res2WithAnother OR Res3WithAnother OR Res4WithAnother;
RatioInhibit := PT_103.Low_Alarm OR DownstreamOutOfRange OR SupplyPressureTrip OR FV_105.Position_Error OR ScreenConflict OR FIC_104.Deviation_Alarm OR LowFlowLatch OR PT_104.Low_Alarm;
FFIC_103(
    PrimaryPV := FT_101.PV,
    SecondaryPV := FT_102.PV,
    RatioSP := 2.0,
    MV_MIN := 0.0,
    MV_MAX := 500.0,
    Inhibit := RatioInhibit);

(* Outputs published to other sections / HMI. *)
FT102_SP_FromRatio := FFIC_103.SlaveSP;
FV105_Feedback_Position := FV_105.Feedback_Pos;

FT_101(
    Scaling_Slope := 31.25,
    Scaling_Offset := -125.0,
    Alarm_Enable := TRUE);
LT_101(
    PV_High := 9.0,
    PV_Low := 1.5,
    Scaling_Slope := 0.625,
    Scaling_Offset := -2.5,
    Alarm_Enable := TRUE);
SumpLevelOutOfRange := LT_101.Low_Alarm OR LT_101.High_Alarm;
FIC_101(
    AUTO := TRUE,
    PV := FT_101.PV,
    SP := FIC_101_SP_m3ph,
    MV_MIN := 0.0,
    MV_MAX := 100.0,
    X0 := 0.0,
    KP := 2.5,
    TR := 0.8,
    TD := 0.2,
    Deviation_Limit := 10.0,
    Inhibit := SumpLevelOutOfRange);
M103A();
Inhibit_101A := SumpLevelOutOfRange OR M103A.DI_Out OR VFD_101A.FB_Fault;
VFD_101A(
    Speed_SP := FIC_101.XOUT,
    Inhibit := Inhibit_101A);
M103B();
Inhibit_101B := SumpLevelOutOfRange OR M103B.DI_Out OR VFD_101B.FB_Fault;
VFD_101B(
    Inhibit := Inhibit_101B);
M103C();
Inhibit_101C := SumpLevelOutOfRange OR M103C.DI_Out OR VFD_101C.FB_Fault;
VFD_101C(
    Inhibit := Inhibit_101C);
M103D();
Inhibit_101D := SumpLevelOutOfRange OR M103D.DI_Out OR VFD_101D.FB_Fault;
VFD_101D(
    Inhibit := Inhibit_101D);
SPUMP_201A();
SPUMP_201B();
FlowDeviationHold(
    IN := FIC_101.Deviation_Alarm,
    PT := T#30s);

(* Outputs published to other sections / HMI. *)
Flow_Deviation_Alarm := FlowDeviationHold.Q;
FT_101_Flow_PV_m3ph := FT_101.PV;
LT_101_SumpLevel_m := LT_101.PV;
FIC_101_MV_Percent := FIC_101.XOUT;

FT_301(
    PV_High := 48.0,
    PV_Low := 8.0,
    Scaling_Slope := 3.125,
    Scaling_Offset := -12.5,
    Alarm_Enable := TRUE);
LT_301(
    Alarm_Enable := TRUE);
ANK_301();
LevelNotAbove20_NOT := NOT LT_301.High_Alarm;
UMP_301A(
    Speed_SP := FIC_301.XOUT,
    Inhibit := PumpInhibit_OR);
UMP_301B(
    Inhibit := PumpInhibit_OR);
PumpsAvailable_OR := UMP_301A.FB_Ready OR UMP_301B.FB_Ready;
NotPumpsAvailable_NOT := NOT PumpsAvailable_OR;
XV_107();
NotXVOpen_NOT := NOT XV_107.FB_Opened;
PumpInhibit_OR := NotXVOpen_NOT OR NotPumpsAvailable_NOT OR ANK_301.Bool_Out OR LT_301.Low_Alarm OR LevelNotAbove20_NOT;
PAH_103();
TAH_101();
ValveTrips_OR := PAH_103.DI_Out OR TAH_101.DI_Out OR LT_301.Low_Alarm OR ANK_301.Bool_Out;
PIDInhibit_OR := PumpInhibit_OR OR ValveTrips_OR;
FIC_301(
    PV := FT_301.PV,
    SP := 30.0,
    MV_MIN := 5.0,
    MV_MAX := 95.0,
    X0 := UMP_301A.FB_ActualSpeed,
    KP := 1.8,
    TR := 0.5,
    TD := 0.05,
    Inhibit := PIDInhibit_OR);
FV_301(
    Open_Limit := 100.0,
    Close_Limit := 0.0,
    Inhibit := ValveTrips_OR);

(* Outputs published to other sections / HMI. *)
FT_301_FlowRate_PV := FT_301.PV;
LT_301_Level_PV := LT_301.PV;
FIC_301_MV_FlowControl_Percent := FIC_301.XOUT;
XV_107_Open_FB := XV_107.FB_Opened;
